// v1.0-cards review board: every card proposed in docs/card-proposals.md, as data. Design lab only; the game
// imports nothing from here. Pure data and behaviour tables (no DOM, no imports) so node can load it.
//
// Card:   {id, name, family, rarity, trigger, text (<=14 words), tile (short tile line), why, kind, replaces?, example}
//   kind: 'new' | 'rework' | 'oath' | 'curse'.  rarity: 'common' | 'rare' | 'legendary' (oaths 'oath', curses 'curse').
//   trigger: a game Trigger id (collect, delivery, wave = Pulse, flash, flash-ends, falling-lift, overfill, rhythm,
//   save, clear, any, always-on, rest) or one of the new ones (proximity, pack, oath, curse).
// Example (chain): {kind:'chain', trigger, labels:[A,B], a:[tiles], b:[tiles], say}  tiles: c(id, opts) | E (empty slot)
// Example (scene): {kind:'scene', labels, frames:[keyA,keyB], caps:[capA,capB], facts?:[[label,a,b]], say}
// "say" may use {a} and {b}: the computed totals of the two chains.

export const FAMILIES = [
  {id: 'position', name: 'Position cards', purpose: 'Where a card sits matters.'},
  {id: 'bridges', name: 'Bridges', purpose: 'Two Triggers in one Chain.'},
  {id: 'overflow', name: 'Overflow and the full meter', purpose: 'Today everything past 100 Sparks is wasted.'},
  {id: 'flying', name: 'Flying well', purpose: 'Skill cards: the hand matters, not only the Chain.'},
  {id: 'light', name: 'Light and dark', purpose: 'Luminance as a build.'},
  {id: 'save', name: 'Save and hearts', purpose: 'Today two cards and no build.'},
  {id: 'scaling', name: 'Scaling cards', purpose: 'Cards that grow over the run.'},
  {id: 'economy', name: 'Economy and Forge', purpose: 'Turn wealth into growth; make the Forge a strategy.'},
  {id: 'oaths', name: 'Oaths and curses', purpose: 'Bargains the player chooses, like the Closed Eye. Never random punishments.'},
  {id: 'rework', name: 'Replace or retire', purpose: 'Boring or beaten cards, given a job of their own.'},
];

